import pandas as pd

def clean(df):
    # Drop exact duplicates
    df = df.drop_duplicates().reset_index(drop=True)

    # Fix Category label variants
    df['Category'] = df['Category'].replace({
        'office supplies': 'Office Supplies'
    })

    return df

def answer(df):
    # Count orders per category
    result = df.groupby('Category').size().to_dict()
    # Drop missing group keys
    result = {k: v for k, v in result.items() if pd.notna(k)}
    return result
